import { useCallback,useEffect,useState } from "react";
import api from "../../api/axios";
import Pagination from "../../components/common/navigation/Pagination";
export default function VendorSupportPage(){
 const [items,setItems]=useState([]);const [page,setPage]=useState(1);const [pagination,setPagination]=useState(null);const [selected,setSelected]=useState(null);const [subject,setSubject]=useState("");const [message,setMessage]=useState("");const [reply,setReply]=useState("");const [loading,setLoading]=useState(true);const [busy,setBusy]=useState(false);const [error,setError]=useState("");const [notice,setNotice]=useState("");
 const load=useCallback(async(targetPage=page)=>{setLoading(true);setError("");try{const r=await api.get("/support/tickets",{params:{page:targetPage,per_page:20}});if(!r?.data?.success)throw new Error("Unexpected support response.");setItems(r.data.data?.data??[]);setPagination(r.data.data?.pagination??null);}catch(e){setError(e?.response?.data?.message||e?.message||"Unable to load tickets.");}finally{setLoading(false);}},[page]);
 useEffect(()=>{void load();},[load]);
 async function open(id){setError("");try{const r=await api.get("/support/tickets/"+id);if(!r?.data?.success)throw new Error("Unable to load ticket.");setSelected(r.data.data);}catch(e){setError(e?.response?.data?.message||e?.message||"Unable to load ticket.");}}
 async function submit(e){e.preventDefault();setBusy(true);setError("");setNotice("");try{const r=await api.post("/support/tickets",{subject,message,category:"store",priority:"normal"});if(!r?.data?.success)throw new Error("Ticket creation failed.");setSubject("");setMessage("");setNotice("Support ticket submitted.");setPage(1);await load(1);if(r.data.data?.ticket?.id)await open(r.data.data.ticket.id);}catch(e){setError(e?.response?.data?.message||e?.message||"Unable to submit ticket.");}finally{setBusy(false);}}
 async function sendReply(e){e.preventDefault();if(!selected||!reply.trim())return;setBusy(true);setError("");try{const r=await api.post("/support/tickets/"+selected.ticket.id+"/messages",{message:reply});if(!r?.data?.success)throw new Error("Reply failed.");setReply("");await open(selected.ticket.id);await load();}catch(e){setError(e?.response?.data?.message||e?.message||"Unable to send reply.");}finally{setBusy(false);}}
 return <div className="container-fluid py-4"><h1 className="h3">Vendor support</h1><p className="text-muted">Contact marketplace support and follow replies about your store, products or orders.</p>{error?<div className="alert alert-danger" role="alert">{error}<button className="btn btn-sm btn-outline-danger ms-2" onClick={()=>void load()}>Retry</button></div>:null}{notice?<div className="alert alert-success" role="status">{notice}</div>:null}
 <div className="row g-4"><div className="col-lg-5"><div className="card border-0 shadow-sm mb-3"><div className="card-body"><h2 className="h5">Create support ticket</h2><form onSubmit={submit}><input className="form-control mb-3" value={subject} onChange={e=>setSubject(e.target.value)} placeholder="Subject" maxLength={180} required/><textarea className="form-control mb-3" rows="4" value={message} onChange={e=>setMessage(e.target.value)} placeholder="Describe your issue (at least 10 characters)" minLength={10} required/><button className="btn btn-primary" disabled={busy}>Submit ticket</button></form></div></div><div className="card border-0 shadow-sm"><div className="card-body"><h2 className="h5">Your tickets</h2>{loading?<p>Loading…</p>:items.length===0?<p className="text-muted">No support tickets yet.</p>:items.map(t=><button key={t.id} onClick={()=>void open(t.id)} className={"w-100 border-bottom py-3 text-start "+(selected?.ticket?.id===t.id?"text-primary":"")}><div className="d-flex justify-content-between"><strong>{t.number}</strong><span className="badge text-bg-secondary">{t.status}</span></div><div>{t.subject}</div><small className="text-muted">{new Date(t.created_at).toLocaleString()}</small></button>)}{pagination&&<Pagination currentPage={pagination.current_page} lastPage={pagination.last_page} onPageChange={setPage}/>}</div></div></div>
 <div className="col-lg-7"><div className="card border-0 shadow-sm"><div className="card-body">{!selected?<p className="text-muted mb-0">Select a ticket to view its conversation.</p>:<><div className="d-flex justify-content-between"><div><h2 className="h5">{selected.ticket.subject}</h2><p className="small text-muted">{selected.ticket.number} · {selected.ticket.status}</p></div><button className="btn-close" aria-label="Close ticket" onClick={()=>setSelected(null)}/></div><div className="border rounded p-3 my-3" style={{maxHeight:400,overflowY:"auto"}}>{selected.messages?.map(m=><div key={m.id} className="mb-3"><strong>{m.author||"Support"}</strong><p className="mb-1 text-break">{m.message}</p><small className="text-muted">{new Date(m.created_at).toLocaleString()}</small></div>)}</div>{!["resolved","closed"].includes(selected.ticket.status)?<form onSubmit={sendReply}><textarea className="form-control mb-2" rows="3" value={reply} onChange={e=>setReply(e.target.value)} minLength={2} maxLength={10000} placeholder="Write a reply…" required/><button className="btn btn-primary" disabled={busy||!reply.trim()}>{busy?"Sending…":"Send reply"}</button></form>:<p className="small text-muted">This ticket is closed.</p>}</>}</div></div></div></div></div>;
}
